package main

import (
	"crypto/rand"
	"encoding/hex"
	"fmt"
	"io"
	"log"
	"net/http"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
	"text/template"
)

var reportTemplate = `\documentclass{article}
\usepackage{graphicx}
\usepackage{hyperref}
\begin{document}
\title{ {{.Title}} }
\author{ {{.Author}} }
\maketitle
\section{Summary}
{{.Summary}}
\section{Details}
{{.Details}}
\end{document}`

type ReportData struct {
	Title   string
	Author  string
	Summary string
	Details string
}

func generateID() string {
	b := make([]byte, 8)
	rand.Read(b)
	return hex.EncodeToString(b)
}

func sanitizeField(input string) string {
	// Basic sanitization - remove obvious shell metacharacters
	replacer := strings.NewReplacer(
		"$", "",
		"`", "",
		";", "",
		"|", "",
		"&", "\\&",
	)
	return replacer.Replace(input)
}

func handleGenerateReport(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "Method not allowed", 405)
		return
	}

	r.ParseForm()
	title := r.FormValue("title")
	author := r.FormValue("author")
	summary := r.FormValue("summary")
	details := r.FormValue("details")

	if title == "" || author == "" {
		http.Error(w, "title and author required", 400)
		return
	}

	// Sanitize inputs
	data := ReportData{
		Title:   sanitizeField(title),
		Author:  sanitizeField(author),
		Summary: sanitizeField(summary),
		Details: sanitizeField(details),
	}

	jobID := generateID()
	workDir := filepath.Join("/tmp/reports", jobID)
	os.MkdirAll(workDir, 0755)

	texFile := filepath.Join(workDir, "report.tex")
	f, err := os.Create(texFile)
	if err != nil {
		http.Error(w, "internal error", 500)
		return
	}

	tmpl, err := template.New("report").Parse(reportTemplate)
	if err != nil {
		http.Error(w, "template error", 500)
		return
	}
	tmpl.Execute(f, data)
	f.Close()

	// Compile LaTeX to PDF
	cmd := exec.Command("pdflatex",
		"-interaction=nonstopmode",
		"-output-directory="+workDir,
		texFile,
	)
	cmd.Dir = workDir
	cmd.Env = append(os.Environ(), "TEXMFHOME="+workDir)
	output, err := cmd.CombinedOutput()
	if err != nil {
		log.Printf("pdflatex error for job %s: %s\n%s", jobID, err, string(output))
		http.Error(w, "PDF generation failed", 500)
		return
	}

	pdfFile := filepath.Join(workDir, "report.pdf")
	pdf, err := os.Open(pdfFile)
	if err != nil {
		http.Error(w, "PDF not found", 500)
		return
	}
	defer pdf.Close()

	w.Header().Set("Content-Type", "application/pdf")
	w.Header().Set("Content-Disposition", fmt.Sprintf("attachment; filename=report-%s.pdf", jobID))
	io.Copy(w, pdf)

	// Cleanup
	os.RemoveAll(workDir)
}

func handleHealth(w http.ResponseWriter, r *http.Request) {
	w.Write([]byte("OK"))
}

func main() {
	http.HandleFunc("/api/reports/generate", handleGenerateReport)
	http.HandleFunc("/health", handleHealth)
	log.Println("Report service listening on :8080")
	log.Fatal(http.ListenAndServe(":8080", nil))
}
